//==============================================================================
// A pure specification function: the number of distinct elements
// in the prefix a[0..n].  By recursion on n.
//
//   prefix_count(a, 0) = 0
//   prefix_count(a, 1) = 1
//   prefix_count(a, n) = prefix_count(a, n-1)
//                      + (if a[n-1] != a[n-2] { 1 } else { 0 })
//==============================================================================

#[verifier::spec]
fn prefix_count(a: &Vec<i32>, n: usize) -> usize {
    decreases(n);
    if n == 0 {
        0
    } else if n == 1 {
        1
    } else {
        let pc = prefix_count(a, n - 1);
        if a[n - 1] != a[n - 2] {
            pc + 1
        } else {
            pc
        }
    }
}

//==============================================================================
// The actual implementation, now equipped with requires/ensures and a loop
// invariant so Verus can verify it matches our spec.
//
// We require that nums is sorted in non‐decreasing order.
