//==============================================================================

#[verifier::requires(
    forall(|i: usize| i + 1 < nums.len() ==> nums[i] <= nums[i + 1])
)]
#[verifier::ensures(
    // ret (the returned usize) equals our pure definition
    ret == prefix_count(nums, nums.len())
)]
fn remove_duplicates(nums: &Vec<i32>) -> usize {
    if nums.is_empty() {
        return 0;
    }
    let mut unique_count = 1;

    // We iterate i from 1..nums.len(), and maintain the invariant that
    //    unique_count == prefix_count(nums, i)
    // and of course 1 <= i <= nums.len(), and we decrease (nums.len() - i).
    #[verifier::invariant(1 <= i && i <= nums.len())]
    #[verifier::invariant(unique_count == prefix_count(nums, i))]
    #[verifier::decreases(nums.len() - i)]
    for i in 1..nums.len() {
        if nums[i] != nums[i - 1] {
            unique_count += 1;
        }
    }

    unique_count
}

